      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><g font-family=\"Arial,sans-serif\"><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Three Kinds of Poesy</text><text x=\"550\" y=\"115\" font-size=\"23\" fill=\"#cccccc\" text-anchor=\"middle\">Tell it, show it, or make it mean something</text><rect x=\"70\" y=\"160\" width=\"300\" height=\"760\" rx=\"18\" fill=\"rgba(245,158,11,0.13)\" stroke=\"#f59e0b\" stroke-width=\"3\"/><text x=\"220\" y=\"220\" font-size=\"26\" fill=\"#ffffff\" text-anchor=\"middle\" font-weight=\"bold\">NARRATIVE</text><circle cx=\"220\" cy=\"350\" r=\"60\" fill=\"rgba(245,158,11,0.25)\" stroke=\"#f59e0b\" stroke-width=\"3\"/><text x=\"220\" y=\"362\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">tells</text><text x=\"220\" y=\"470\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">imitation of</text><text x=\"220\" y=\"504\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">history, enlarged</text><text x=\"220\" y=\"538\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\"></text><text x=\"220\" y=\"572\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">wars and love</text><text x=\"220\" y=\"606\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\"></text><text x=\"220\" y=\"640\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">Homer, Virgil,</text><text x=\"220\" y=\"674\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">Spenser</text><path d=\"M160 790 L220 760 L280 790 L280 870 L220 840 L160 870 Z\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"4\"/><rect x=\"400\" y=\"160\" width=\"300\" height=\"760\" rx=\"18\" fill=\"rgba(239,68,68,0.13)\" stroke=\"#ef4444\" stroke-width=\"3\"/><text x=\"550\" y=\"220\" font-size=\"26\" fill=\"#ffffff\" text-anchor=\"middle\" font-weight=\"bold\">REPRESENT-</text><text x=\"550\" y=\"252\" font-size=\"26\" fill=\"#ffffff\" text-anchor=\"middle\" font-weight=\"bold\">ATIVE</text><circle cx=\"550\" cy=\"350\" r=\"60\" fill=\"rgba(239,68,68,0.25)\" stroke=\"#ef4444\" stroke-width=\"3\"/><text x=\"550\" y=\"362\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">shows</text><text x=\"550\" y=\"470\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">\"a visible history\"</text><text x=\"550\" y=\"504\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">actions as if</text><text x=\"550\" y=\"538\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">present</text><text x=\"550\" y=\"572\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\"></text><text x=\"550\" y=\"606\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">drama: the Globe;</text><text x=\"550\" y=\"640\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">today, film</text><text x=\"550\" y=\"674\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\"></text><path d=\"M480 870 L480 790 Q550 740 620 790 L620 870\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"4\"/><rect x=\"730\" y=\"160\" width=\"300\" height=\"760\" rx=\"18\" fill=\"rgba(20,184,166,0.13)\" stroke=\"#14b8a6\" stroke-width=\"3\"/><text x=\"880\" y=\"220\" font-size=\"26\" fill=\"#ffffff\" text-anchor=\"middle\" font-weight=\"bold\">ALLUSIVE</text><circle cx=\"880\" cy=\"350\" r=\"60\" fill=\"rgba(20,184,166,0.25)\" stroke=\"#14b8a6\" stroke-width=\"3\"/><text x=\"880\" y=\"362\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">means</text><text x=\"880\" y=\"470\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">story built to</text><text x=\"880\" y=\"504\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">carry a point</text><text x=\"880\" y=\"538\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\"></text><text x=\"880\" y=\"572\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">parables, fables</text><text x=\"880\" y=\"606\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\"></text><text x=\"880\" y=\"640\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">Aesop, the Seven</text><text x=\"880\" y=\"674\" font-size=\"20\" fill=\"#cccccc\" text-anchor=\"middle\">Sages, hieroglyphs</text><circle cx=\"880\" cy=\"815\" r=\"45\" fill=\"none\" stroke=\"#14b8a6\" stroke-width=\"4\"/><text x=\"880\" y=\"832\" font-size=\"44\" fill=\"#14b8a6\" text-anchor=\"middle\" font-weight=\"bold\">!</text><text x=\"550\" y=\"1000\" font-size=\"24\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Drama is \"representative\" poesy</text></g></svg>",
      "caption": "Narrative, representative and allusive poesy compared"
