      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><g font-family=\"Arial,sans-serif\"><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Knowledge Check</text><text x=\"550\" y=\"115\" font-size=\"23\" fill=\"#cccccc\" text-anchor=\"middle\" font-weight=\"normal\">The Great Instauration</text><rect x=\"60\" y=\"150\" width=\"980\" height=\"8\" rx=\"4\" fill=\"#10b981\"/><text x=\"550\" y=\"215\" font-size=\"26\" fill=\"#10b981\" text-anchor=\"middle\" font-weight=\"bold\">Which book became part one?</text><rect x=\"150\" y=\"270\" width=\"800\" height=\"120\" rx=\"16\" fill=\"rgba(255,215,0,0.2)\" stroke=\"#ffd700\" stroke-width=\"5\"/><text x=\"270\" y=\"340\" font-size=\"28\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Part 1</text><text x=\"400\" y=\"338\" font-size=\"24\" fill=\"#ffffff\" text-anchor=\"start\" font-weight=\"normal\">Divisions of the sciences</text><rect x=\"150\" y=\"420\" width=\"800\" height=\"120\" rx=\"16\" fill=\"rgba(59,130,246,0.1)\" stroke=\"#3b82f6\" stroke-width=\"3\"/><text x=\"270\" y=\"490\" font-size=\"28\" fill=\"#3b82f6\" text-anchor=\"middle\" font-weight=\"bold\">Part 2</text><text x=\"400\" y=\"488\" font-size=\"24\" fill=\"#ffffff\" text-anchor=\"start\" font-weight=\"normal\">New Organon</text><rect x=\"150\" y=\"570\" width=\"800\" height=\"120\" rx=\"16\" fill=\"rgba(20,184,166,0.1)\" stroke=\"#14b8a6\" stroke-width=\"3\"/><text x=\"270\" y=\"640\" font-size=\"28\" fill=\"#14b8a6\" text-anchor=\"middle\" font-weight=\"bold\">Part 3</text><text x=\"400\" y=\"638\" font-size=\"24\" fill=\"#ffffff\" text-anchor=\"start\" font-weight=\"normal\">Natural history</text><rect x=\"150\" y=\"720\" width=\"800\" height=\"120\" rx=\"16\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"3\"/><text x=\"270\" y=\"790\" font-size=\"28\" fill=\"#8b5cf6\" text-anchor=\"middle\" font-weight=\"bold\">Parts 4–6</text><text x=\"400\" y=\"788\" font-size=\"24\" fill=\"#ffffff\" text-anchor=\"start\" font-weight=\"normal\">Ladder, forerunners, active science</text><text x=\"900\" y=\"342\" font-size=\"48\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">?</text><text x=\"550\" y=\"960\" font-size=\"23\" fill=\"#cccccc\" text-anchor=\"middle\" font-weight=\"normal\">Bacon’s 1605 map was rebuilt in Latin for all of Europe.</text></g></svg>",
